function ff_checked(element, message)
{
    if (element.checked) 
        return ''; 
    else {
        if (message=='') message = element.name+" is not checked.\n";
        ff_validationFocus(element.name);
        return message;
    } 
}

function ff_resetForm(element, action) {
    // Accéder au formulaire directement par son ID sans utiliser eval
    var form = document.getElementById(ff_processor.form_id);
    
    // Si le formulaire est trouvé, le réinitialiser
    if (form) {
        form.reset();
    } else {
        console.error('Formulaire non trouvé avec l\'ID:', ff_processor.form_id);
    }
}
