var bfEventPrices = {'Web accessibility basics': 120, 'Joomla administration': 180, 'Advanced forms workshop': 240};
var bfEventLunch = 15, bfEventReduced = 0.2;
function bfEventTotal() {
  var price = bfEventPrices[bfField('Training')] || 0;
  var people = Number(bfField('Participants')) || 0;
  var reduced = bfField('Rate') === 'Reduced';
  var lunch = bfField('Lunch') ? bfEventLunch : 0;
  var each = price * (reduced ? 1 - bfEventReduced : 1) + lunch;
  ff_getElementByName('PricePerPerson').value = each.toFixed(2);
  ff_getElementByName('Discount').value = (price * (reduced ? bfEventReduced : 0) * people).toFixed(2);
  ff_getElementByName('Total').value = (each * people).toFixed(2);
  if (typeof populateSummarizers === 'function') { populateSummarizers(); }
}
function ff_Training_action(element, action) { bfEventTotal(); }

